/**
 * Writing to localStorage without letting bulk data cost someone their work.
 *
 * localStorage is one ~5MB budget shared by everything, and it stores UTF-16 —
 * so a character costs two bytes and a generous-looking character limit is
 * twice as generous as it looks. When the budget runs out `setItem` throws, and
 * an unguarded write loses whatever it was trying to save.
 *
 * That failure mode is not evenly bad. Terminal scrollback can be regenerated by
 * scrolling; a list of projects cannot be regenerated at all. So a write that
 * runs out of room does not simply give up: it evicts the things that can be
 * lived without and tries again, in the order below.
 */

/** Dropped, in this order, to make room for something that matters more. */
const EVICTABLE = [
  // Pure convenience. Costs the most and is worth the least.
  "pitwall-terminal-history",
  // Rediscovered the next time a dev server is noticed.
  "pitwall-preview-urls",
];

function isQuotaError(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  // Browsers disagree on the name, and Safari's code is the only signal it gives.
  return (
    error.name === "QuotaExceededError" ||
    error.name === "NS_ERROR_DOM_QUOTA_REACHED" ||
    (error as { code?: number }).code === 22
  );
}

/**
 * Stores a value, making room if there is none.
 *
 * Returns whether it landed. Callers that care can react; most cannot do
 * anything useful about it and simply must not throw, because these writes
 * happen inside React effects where an exception takes the render with it.
 */
export function writeStored(key: string, value: string): boolean {
  if (typeof window === "undefined") return false;

  try {
    window.localStorage.setItem(key, value);
    return true;
  } catch (error) {
    if (!isQuotaError(error)) return false;

    for (const victim of EVICTABLE) {
      // Never evict on behalf of the thing being evicted: terminal history
      // asking for room must not clear terminal history and call that success.
      if (victim === key) continue;
      if (window.localStorage.getItem(victim) === null) continue;

      window.localStorage.removeItem(victim);
      try {
        window.localStorage.setItem(key, value);
        return true;
      } catch (retryError) {
        if (!isQuotaError(retryError)) return false;
        // Still short. Try the next victim.
      }
    }

    return false;
  }
}

/** Convenience for the common case of storing JSON. */
export function writeStoredJson(key: string, value: unknown): boolean {
  try {
    return writeStored(key, JSON.stringify(value));
  } catch {
    // A value with a cycle in it is a programming error, not a storage one.
    return false;
  }
}
